def extract_missing(numbers, start, end):
    # Sort the list and remove duplicates
    numbers = sorted(set(numbers))

    missing_ranges = []
    current = start

    # Iterate through the list and identify missing ranges
    for number in numbers:
        if number > current:
            if current + 1 == number:
                if missing_ranges and isinstance(missing_ranges[-1], int):
                    missing_ranges[-1] = (missing_ranges[-1], number - 1)
                else:
                    missing_ranges.append((current, number - 1))
            else:
                missing_ranges.append((current, number - 1))
        current = number + 1

    # Check for any range missing after the last number in the list
    if current <= end:
        if current + 1 == end + 1:
            if missing_ranges and isinstance(missing_ranges[-1], int):
                missing_ranges[-1] = (missing_ranges[-1], end)
            else:
                missing_ranges.append((current, end))
        else:
            missing_ranges.append((current, end))

    # Convert single element ranges to integers
    missing_ranges = [x if isinstance(x, tuple) else x for x in missing_ranges]

