def min_Ops(arr, k):
    if k == 0:
        return float('inf')

    n = len(arr)
    if n <= 1:
        return 0

    arr.sort()
    prefix_sum = [0] * n
    prefix_sum[0] = arr[0]

    for i in range(1, n):
        prefix_sum[i] = prefix_sum[i - 1] + arr[i]

    def operations(target):
        ops = 0
        left, right = 0, n - 1
        while left <= right:
            if arr[left] + k - 1 >= target:
                ops += (arr[left] - target) * (left + 1)
                left += 1
            else:
                ops += (target - arr[right] - 1) * (n - right)
                right -= 1
        return ops

    l, r = arr[0], arr[-1]
    result = float('inf')

    while l <= r:
        mid1 = l + (r - l) // 3
        mid2 = r - (r - l) // 3

        if operations(mid1) < operations(mid2):
            r = mid2 - 1
            result = min(result, operations(mid1))
        else:
            l = mid1 + 1
            result = min(result, operations(mid2))

    return result if result != float('inf') else -1
