    def cost(mid):
        ops = 0
        current_sum = 0
        for i in range(n):
            if i >= k:
                current_sum += arr[i - k]
            if i >= k - 1:
                ops += (prefix_sum[i] - current_sum) - mid * (k)
                current_sum -= arr[i - k + 1] if i >= k else 0
        return ops

    low, high = min(arr), total_sum // n + 1
    result = float('inf')

    while low <= high:
        mid = (low + high) // 2
        if cost(mid) <= total_sum - mid * n:
            result = min(result, cost(mid))
            high = mid - 1
        else:
            low = mid + 1

