def zigzag(n, k):
    if k == 1 or k == n:
        return 1
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][1] = 1
        dp[i][i] = 1
    for i in range(2, n + 1):
        for j in range(2, min(i, k) + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
    return dp[n][k]
