def zigzag(n, k):
    if k < 0 or k >= n:
        return 0
    dp = [[0] * k for _ in range(n)]
    for j in range(k):
        dp[0][j] = 1
    for i in range(1, n):
        for j in range(k):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i - 1][j - 1]
            if j < k - 1:
                dp[i][j] -= dp[i - 1][j + 1]
    return dp[n - 1][k - 1]
