    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def count_pairs(n):
        return n * (n + 1) // 2

    count = 0
    for d in range(1, r + 1):
        # Number of ways to choose two points on the circle that are d units apart
        # This is equivalent to the number of lattice points on a circle of radius d
        # which is given by 4 * number of solutions to x^2 + y^2 = d^2
        if d**2 <= r**2:
            count += 4 * (count_pairs((r**2 - d**2) // (2 * d)) if d != 0 else 1)

