def count_Rectangles(r):
    count = 0
    # Iterate over possible x and y coordinates
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            # Check if the point (x, y) is inside or on the circle
            if x * x + y * y <= r * r:
                # Count rectangles with sides parallel to the axes
                for width in range(1, 2 * r + 1):
                    for height in range(1, 2 * r + 1):
                        # Check opposite corner (x + width, y + height)
                        if (x + width) * (x + width) + (y + height) * (y + height) <= r * r:
                            count += 1
                        # Check opposite corner (x - width, y + height)
                        if (x - width) * (x - width) + (y + height) * (y + height) <= r * r:
                            count += 1
                        # Check opposite corner (x + width, y - height)
                        if (x + width) * (x + width) + (y - height) * (y - height) <= r * r:
                            count += 1
                        # Check opposite corner (x - width, y - height)
                        if (x - width) * (x - width) + (y - height) * (y - height) <= r * r:
                            count += 1
    # Each rectangle is counted 4 times, so divide by 4
    return count // 4

