def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must contain at least two integers.")

    # Initialize variables to store the two largest and two smallest values
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    # Traverse the array to find the two largest and two smallest numbers
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Return the maximum product of either the two largest numbers or the two smallest numbers
    return max(max1 * max2, min1 * min2)
